INSERT INTO `ltu_phrases` VALUES (1314, '9a7a2d57-e731-46a2-bc4e-3a40529666b5', 2, 7, 599, 'accepted', 'validation', ':attribute を承認してください。', '[\"attribute\"]', '2023-10-28 21:16:14', '2023-10-28 21:16:14');
INSERT INTO `ltu_phrases` VALUES (1315, '9a7a2d57-ee3e-484a-bcaf-97856dea31be', 2, 7, 600, 'accepted_if', 'validation', ':other が :value の場合、:attribute を承認する必要があります。', '[\"other\", \"value\", \"attribute\"]', '2023-10-28 21:16:14', '2023-10-28 21:16:14');
INSERT INTO `ltu_phrases` VALUES (1316, '9a7a2d57-f4e8-4685-85ef-1ea10d965d54', 2, 7, 601, 'active_url', 'validation', ':attribute は、有効なURLではありません。', '[\"attribute\"]', '2023-10-28 21:16:14', '2023-10-28 21:16:14');
INSERT INTO `ltu_phrases` VALUES (1317, '9a7a2d57-fc11-4fd7-9749-5b2ffa149683', 2, 7, 602, 'after', 'validation', ':attribute には、:date より後の日付を指定してください。', '[\"attribute\", \"date\"]', '2023-10-28 21:16:14', '2023-10-28 21:16:14');
INSERT INTO `ltu_phrases` VALUES (1318, '9a7a2d58-0306-4786-b69a-fc349b3e87b8', 2, 7, 603, 'after_or_equal', 'validation', ':attribute には、:date 以降の日付を指定してください。', '[\"attribute\", \"date\"]', '2023-10-28 21:16:14', '2023-10-28 21:16:14');
INSERT INTO `ltu_phrases` VALUES (1319, '9a7a2d58-09e6-4972-b14a-7802b07ff6f6', 2, 7, 604, 'alpha', 'validation', ':attribute には、アルファベッドのみ使用できます。', '[\"attribute\"]', '2023-10-28 21:16:14', '2023-10-28 21:16:14');
INSERT INTO `ltu_phrases` VALUES (1320, '9a7a2d58-10d7-43c2-8b1b-06885ed4036d', 2, 7, 605, 'alpha_dash', 'validation', ':attribute には、英数字(\'A-Z\',\'a-z\',\'0-9\')とハイフンと下線(\'-\',\'_\')が使用できます。', '[\"attribute\"]', '2023-10-28 21:16:14', '2023-10-28 21:16:14');
INSERT INTO `ltu_phrases` VALUES (1321, '9a7a2d58-1811-4a8c-be11-e5f0308e8c2c', 2, 7, 606, 'alpha_num', 'validation', ':attribute には、英数字(\'A-Z\',\'a-z\',\'0-9\')が使用できます。', '[\"attribute\"]', '2023-10-28 21:16:14', '2023-10-28 21:16:14');
INSERT INTO `ltu_phrases` VALUES (1322, '9a7a2d58-1f13-4d18-88aa-76f7e81f459c', 2, 7, 607, 'array', 'validation', ':attribute には、配列を指定してください。', '[\"attribute\"]', '2023-10-28 21:16:14', '2023-10-28 21:16:14');
INSERT INTO `ltu_phrases` VALUES (1323, '9a7a2d58-2888-4a6d-adc3-67e6981b7739', 2, 7, 608, 'ascii', 'validation', ':attribute には、英数字と記号のみ使用可能です。', '[\"attribute\"]', '2023-10-28 21:16:14', '2023-10-28 21:16:14');
INSERT INTO `ltu_phrases` VALUES (1324, '9a7a2d58-2fff-4e62-a9b6-e8b54012e538', 2, 7, 609, 'before', 'validation', ':attribute には、:date より前の日付を指定してください。', '[\"attribute\", \"date\"]', '2023-10-28 21:16:14', '2023-10-28 21:16:14');
INSERT INTO `ltu_phrases` VALUES (1325, '9a7a2d58-36fc-4ef1-bc9a-4f8a35bddba3', 2, 7, 610, 'before_or_equal', 'validation', ':attribute には、:date 以前の日付を指定してください。', '[\"attribute\", \"date\"]', '2023-10-28 21:16:14', '2023-10-28 21:16:14');
INSERT INTO `ltu_phrases` VALUES (1326, '9a7a2d58-3e06-43fc-85c2-3b52ca963dc0', 2, 7, 611, 'between.array', 'validation', ':attribute の項目は、:min 個から :max 個にしてください。', '[\"attribute\", \"min\", \"max\"]', '2023-10-28 21:16:14', '2023-10-28 21:16:14');
INSERT INTO `ltu_phrases` VALUES (1327, '9a7a2d58-44d5-4194-8ca8-3e532ca874cf', 2, 7, 612, 'between.file', 'validation', ':attribute には、:min KBから :max KBまでのサイズのファイルを指定してください。', '[\"attribute\", \"min\", \"max\"]', '2023-10-28 21:16:14', '2023-10-28 21:16:14');
INSERT INTO `ltu_phrases` VALUES (1328, '9a7a2d58-4c23-4936-9b71-8af6dc8e62cd', 2, 7, 613, 'between.numeric', 'validation', ':attribute には、:minから、:maxまでの数字を指定してください。', '[\"attribute\", \"min\", \"max\"]', '2023-10-28 21:16:14', '2023-10-28 21:16:14');
INSERT INTO `ltu_phrases` VALUES (1329, '9a7a2d58-5306-4e06-acc4-ae488f670077', 2, 7, 614, 'between.string', 'validation', ':attribute は、:min文字から:max文字にしてください。', '[\"attribute\", \"min\", \"max\"]', '2023-10-28 21:16:14', '2023-10-28 21:16:14');
INSERT INTO `ltu_phrases` VALUES (1330, '9a7a2d58-5b43-4861-aba0-d5695a53188c', 2, 7, 615, 'boolean', 'validation', ':attribute には、\'true\'か\'false\'を指定してください。', '[\"attribute\"]', '2023-10-28 21:16:14', '2023-10-28 21:16:14');
INSERT INTO `ltu_phrases` VALUES (1331, '9a7a2d58-6275-494f-bcaf-26f0ff6cb773', 2, 7, 616, 'can', 'validation', ':attribute  フィールドには不正な値が含まれています。', '[\"attribute\"]', '2023-10-28 21:16:14', '2023-10-28 21:16:14');
INSERT INTO `ltu_phrases` VALUES (1332, '9a7a2d58-695d-4ac7-8b7a-90a92a503692', 2, 7, 617, 'confirmed', 'validation', ':attribute と:attribute 確認が一致しません。', '[\"attribute\", \"attribute\"]', '2023-10-28 21:16:14', '2023-10-28 21:16:14');
INSERT INTO `ltu_phrases` VALUES (1333, '9a7a2d58-7051-4dd0-a2e0-d18b3ff8453b', 2, 7, 618, 'current_password', 'validation', 'パスワードが正しくありません。', NULL, '2023-10-28 21:16:14', '2023-10-28 21:16:14');
INSERT INTO `ltu_phrases` VALUES (1334, '9a7a2d58-772c-4c63-87dd-baadc736534c', 2, 7, 226, 'date', 'validation', ':attribute は、正しい日付ではありません。', '[\"attribute\"]', '2023-10-28 21:16:14', '2023-10-28 21:16:14');
